  COURSES.push({id:'full-library', library:true, icon:'▤', color:'navy', title:'Полная база Mavis Knowledge', eyebrow:'Доступ руководителя', roles:['leader'], lead:'Все загруженные учебные материалы: продукты, продажи, экспертный отдел, Bitrix24 и регламенты.', sources:[...new Set([...COURSES.flatMap(course=>course.sources),...FULL_LIBRARY_EXTRA_SOURCES])], check:{q:'Где руководитель открывает полный первоисточник по теме?',options:['В «Полной базе Mavis Knowledge»','Только в карточке стажёра','В переписке с помощником'],answer:0,order:['Открыть раздел','Выбрать первоисточник','Использовать материал в проверке стажёра']}});
  const traineeLesson=(title,lead,sections)=>`<section class="trainee-lesson"><span>МАТЕРИАЛ СТАЖИРОВКИ</span><h2>${esc(title)}</h2><p class="trainee-lesson-lead">${esc(lead)}</p>${sections.map(section=>`<article><h3>${esc(section.title)}</h3>${section.text?`<p>${esc(section.text)}</p>`:''}${section.items?.length?`<ul>${section.items.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:''}</article>`).join('')}</section>`;
  const bitrixGuide=()=>`<section class="bitrix-guide" aria-label="Схема карточки Bitrix24"><div class="bitrix-guide-head"><span>КАРТА КАРТОЧКИ BITRIX24</span><h3>Что и где фиксировать</h3><p>Это учебная схема по интерфейсу CRM: без реальных клиентов и персональных данных.</p></div><div class="bitrix-screen"><div class="bitrix-stages"><b>Новый лид</b><b>В работе</b><b>Сбор данных</b><b>Предложение</b><b>Следующий шаг</b></div><div class="bitrix-screen-body"><div class="bitrix-fields"><strong>Левая часть: факты</strong><p><b>Клиент и контакт.</b> Компания, имя, удобный канал связи.</p><p><b>Источник и тип клиента.</b> Откуда пришло обращение и кто принимает решение.</p><p><b>Продукт и задача.</b> Что нужно оформить, для какого объекта или деятельности.</p><p><b>Условия.</b> Срок, документы, специалисты, сумма и оплата — только после подтверждения.</p></div><div class="bitrix-timeline"><strong>Правая часть: история и действие</strong><p class="bitrix-note">Комментарий: «Клиенту нужен …; подтверждено …; уточняем …»</p><p class="bitrix-task">Дело: «До 14:00 12 ноября — получить перечень работ и назначить звонок эксперту»</p><p class="bitrix-note">После ответа эксперта: обновить карточку, отправить КП и поставить дату обсуждения.</p></div></div></div><div class="bitrix-guide-steps"><article><b>1. Откройте обращение</b><span>Проверьте, что это: новый лид или уже действующая сделка.</span></article><article><b>2. Соберите подтверждённые факты</b><span>Не подменяйте пустые поля предположениями. Неясное — вопросом клиенту или эксперту.</span></article><article><b>3. Оставьте понятную историю</b><span>Коллега должен за минуту понять задачу, риск и статус без прослушивания звонка.</span></article><article><b>4. Создайте дело</b><span>У дела всегда есть действие, дата, ответственный и ожидаемый результат.</span></article></div></section>`;
  const priceGuide=()=>`<section class="price-guide"><div class="price-guide-head"><span>РАБОЧИЙ ИНСТРУМЕНТ</span><h3>Прайс: как найти строку и не назвать цену наугад</h3><p>Прайс — исходная точка расчёта. Он не заменяет диагностику, проверку условий и согласование нестандартной ситуации с экспертом.</p></div><div class="price-steps"><article><b>01</b><h4>Сначала определите маршрут</h4><p>Зафиксируйте продукт, вид работ или продукции, цель обращения, регион, срок и то, что у клиента уже есть.</p></article><article><b>02</b><h4>Найдите базовую строку</h4><p>Сверьте наименование услуги, объём, класс/направление и включённые работы. Смотрите дату актуальности прайса.</p></article><article><b>03</b><h4>Отделите цену услуги от внешних платежей</h4><p>Госпошлины, работы подрядчика, подбор специалистов и дополнительные услуги не обещайте «включёнными», пока это не подтверждено.</p></article><article><b>04</b><h4>Проверьте исключения</h4><p>Если нет точного совпадения строки, есть срочность, нестандартный объект или неполные данные — создайте вопрос эксперту, не придумывайте сумму.</p></article><article><b>05</b><h4>Зафиксируйте расчёт</h4><p>В CRM укажите версию прайса, выбранную строку, что входит, чего не хватает и когда клиенту вернётся подтверждённое предложение.</p></article></div><article class="price-checklist"><h3>Мини-чек-лист перед КП</h3><ul><li>Цена соответствует конкретной услуге и исходным данным.</li><li>Клиенту понятно, что включено, а что рассчитывается отдельно.</li><li>Для нестандартного случая есть вопрос эксперту и срок ответа.</li><li>В карточке сделки есть дата следующего касания.</li></ul></article></section>`;
  const TRAINEE_COURSES = [
    {id:'tr-company',icon:'◎',color:'teal',title:'Компания, клиент и ценность',eyebrow:'День 01 · знакомство',lead:'Кому помогают Mavis и как объяснить ценность услуг без общих фраз.',sources:['Компания, клиент и ценность'],practice:'sales',check:COURSES[5].check,content:traineeLesson('Компания, клиент и ценность','Начните не с перечня документов, а с понимания задачи клиента и риска, который он хочет снять.',[{title:'Что изучить',items:['Чем занимается компания и какие задачи клиентов решает.','Кто наш клиент: организации, которым нужны разрешительные документы, подтверждение компетенций или системы менеджмента.','Как устроен отдел продаж: менеджер собирает факты и фиксирует следующий шаг; эксперт подтверждает требования и маршрут.']},{title:'Что написать после изучения',items:['Чем занимается компания — своими словами.','Кто наш клиент и почему ему выгодно работать с нами.','Какие продукты вы начали изучать и что уже поняли.']}])},
    {id:'tr-products',icon:'▧',color:'teal',title:'Основные продукты: единая карта',eyebrow:'День 01 · продукты',lead:'СПК, аттестация, ISO и СУОТ — один учебный материал вместо кодов и паспортов.',sources:['Основные продукты: единая карта'],practice:'spk',check:COURSES[0].check,content:traineeLesson('Основные продукты: единая карта','Для каждого продукта стажёр должен видеть не внутренний код, а логику: кому нужен документ, что проверяем и какой риск снимаем.',[{title:'СПК',text:'Производственный контроль для строительной организации. До обещаний уточняем виды работ, объект, специалистов, средства измерения и исходные документы.'},{title:'Аттестация',text:'Подтверждает возможность организации выполнять заявленные направления работ. Требования зависят от направления, специалистов, стажа и документов. Отдельные коды направлений не являются отдельными плитками стажировки.'},{title:'ISO и СУОТ',text:'ISO 9001 помогает подтвердить систему менеджмента качества; СУОТ 45001 — работу по охране труда. Уточняйте цель: тендер, требование заказчика, внутренний порядок или безопасность.'},{title:'Конспект по каждому продукту',items:['Как называется документ и с каким органом или процедурой он связан.','Срок действия и есть ли периодическая оценка.','Основные требования и от чего они зависят.','Что получает клиент и какие риски остаются без документа или без периодической оценки.']}])},
    {id:'tr-product-review',icon:'↻',color:'orange',title:'Повторение продуктов и вопросы',eyebrow:'День 02 · продукты',lead:'Закрепите продукты и подготовьте вопросы для самостоятельной проверки.',sources:['Повторение продуктов и вопросы'],practice:'iso-suot',check:COURSES[2].check,content:traineeLesson('Повторение продуктов и вопросы','Продолжите изучать СПК, аттестацию, ISO и СУОТ. Не заучивайте названия: проверьте, можете ли объяснить назначение продукта клиенту.',[{title:'Проверьте себя',items:['Могу назвать, кому подходит каждый продукт.','Понимаю, какие данные надо собрать до расчёта.','Не обещаю срок и результат без проверки требований.']},{title:'Задание',items:['Составьте список вопросов, которые следует уточнить до расчёта.','Сделайте краткий конспект: что это, кому нужно, зачем клиенту оформлять.']}])},
    {id:'tr-script',icon:'↗',color:'yellow',title:'Скрипт первого разговора',eyebrow:'День 02 · скрипт',lead:'Последовательность разговора: польза, диагностика, презентация, КП и зафиксированный контакт.',sources:['Скрипт первого разговора'],practice:'sales',check:COURSES[5].check,content:traineeLesson('Скрипт первого разговора','Скрипт — не текст для механического чтения. Это порядок, который помогает не потерять цель разговора.',[{title:'Структура разговора',items:['Приветствие и причина звонка: коротко объясните, что проверите и чем это полезно клиенту.','Диагностика: уточните работы или продукцию, объект, сроки, документы, специалистов и цель клиента.','Презентация: назовите подходящий маршрут только на основании подтверждённых фактов.','КП: не отправляйте типовой файл без минимальных данных и договорённости, когда его обсудите.','Следующее касание: дата, канал, действие и ответственный.']},{title:'Задание',text:'Подготовьте собственный примерный скрипт первого звонка: приветствие, вопросы, презентация, проверка понимания, КП и следующая связь.'}])},
    {id:'tr-price-kp',icon:'◇',color:'yellow',title:'Прайс и коммерческое предложение',eyebrow:'День 02 · КП',lead:'Как собрать КП по запросу, а не отправить клиенту случайный шаблон.',sources:['Прайс и коммерческое предложение'],practice:'sales',check:COURSES[5].check,content:traineeLesson('Прайс и коммерческое предложение','Прайс помогает сориентироваться, но сам по себе не заменяет диагностику и подтверждение маршрута.',[{title:'Перед подготовкой КП',items:['Зафиксируйте компанию, задачу, объект или продукцию и факты, которые клиент подтвердил.','Проверьте продукт, объём работ, исходные документы, стоимость и возможные дополнительные расходы.','Согласуйте, когда и как клиент разберёт предложение.']},{title:'Задание',items:['Изучите прайс и шаблоны КП по СПК и аттестации.','Подготовьте КП по учебному кейсу и передайте его на проверку.']}])},
    {id:'tr-calls',icon:'◉',color:'yellow',title:'Разбор звонков',eyebrow:'День 02 · практика',lead:'Слушайте реальные примеры и учитесь видеть факты, пользу и качество следующего шага.',sources:['Разбор звонков'],practice:'sales',check:COURSES[5].check,content:traineeLesson('Разбор звонков','После каждого звонка оценивайте не «понравилось / не понравилось», а конкретные действия менеджера.',[{title:'Проверьте в каждом звонке',items:['Какие факты о клиенте выяснил менеджер.','Как сформулировал пользу и не обещал лишнего.','Есть ли конкретный следующий шаг: дата, канал, действие и ответственный.']},{title:'Задание',items:['В Google Doc выпишите сильные стороны хороших звонков и ошибки слабых.','Подготовьте вопросы: что непонятно, что можно улучшить, какие ошибки услышали.']}])},
    {id:'tr-practice',icon:'✎',color:'aqua',title:'Кейс: первый разговор',eyebrow:'День 03 · самостоятельная практика',lead:'Разберите запрос клиента и подготовьте свой ответ прямо в Academy.',sources:['Кейс: первый разговор'],practice:'sales',check:COURSES[5].check,content:traineeLesson('Кейс: первый разговор','Это самостоятельная отработка: вы не ждёте куратора, а строите безопасный первый разговор по фактам из кейса.',[{title:'Ситуация',text:'Клиент просит «срочно оформить документ для строительных работ», но не называет вид работ, объект, специалистов и действующие документы.'},{title:'Ваш план ответа',items:['Начните с короткого приветствия и объясните, что сначала уточните задачу.','Составьте вопросы о работах, объекте, сроке, специалистах и документах.','Объясните, почему нельзя назвать срок и документ без проверки.','Согласуйте конкретный следующий шаг: какие данные клиент пришлёт и когда вы вернётесь с ответом.']},{title:'Практика',text:'Нажмите «Открыть практику» и напишите свой сценарий. Ответ сохранится как самостоятельная практика.'}])},
    {id:'tr-bitrix',icon:'▦',color:'aqua',title:'Как вести лид и сделку в Bitrix24',eyebrow:'День 03 · CRM',lead:'Пошагово: что заполнить, как оставить комментарий и как назначить следующее действие.',sources:['Как вести лид и сделку в Bitrix24'],practice:'bitrix',check:COURSES[6].check,content:traineeLesson('Как вести лид и сделку в Bitrix24','Bitrix — рабочая память команды. Карточка должна быть понятна коллеге, который не участвовал в разговоре: что происходит с клиентом, что уже подтверждено и что команда делает дальше.',[{title:'Лид и сделка: в чём разница',text:'Лид — первичное обращение, по которому ещё нужно понять задачу и квалифицировать клиента. Сделка — работа по уже понятному запросу. В обоих случаях фиксируйте только подтверждённые клиентом сведения.'},{title:'Что заполнить после первого контакта',items:['Название компании, контакт и согласованный канал связи.','Источник обращения, тип клиента и продукт или направление, если они уже понятны.','Задачу клиента: какие работы, объект или продукцию он описывает; зачем нужен документ и к какому сроку.','Условия: продукт, сумма и оплата — только если они подтверждены. Пустое поле лучше, чем придуманное значение.']},{title:'Как оформить итог разговора',items:['В комментарии кратко разделите факты, открытые вопросы и то, что проверяем.','Создайте дело: действие, дата, ответственный и ожидаемый результат. «Перезвонить позже» — не задача.','После ответа эксперта обновите карточку, отправьте согласованный материал и назначьте обсуждение с клиентом.']}])+bitrixGuide()},
    {id:'tr-tables',icon:'▤',color:'aqua',title:'Прайс и рабочие таблицы: расчёт без догадок',eyebrow:'День 03 · инструменты',lead:'Как использовать прайс, проверить состав услуги и подготовить корректный вопрос эксперту.',sources:['Прайс и рабочие таблицы: расчёт без догадок'],practice:'bitrix',check:COURSES[6].check,content:traineeLesson('Прайс и рабочие таблицы: расчёт без догадок','Прайс помогает найти базовую стоимость. Верная цена появляется только после того, как вы поняли задачу клиента и проверили условия.',[{title:'Что должно быть перед расчётом',items:['Продукт или услуга, цель клиента и срок.','Вид работ, объект, объём или характеристики продукции — в зависимости от направления.','Действующие документы, сведения о специалистах и все условия, которые могут изменить маршрут.']},{title:'Самостоятельное задание',text:'По учебному кейсу выпишите недостающие для расчёта данные, найдите точку, где нужна проверка эксперта, и составьте один точный вопрос. Не называйте клиенту сумму до ответа по нестандартным условиям.'}])+priceGuide()},
    {id:'tr-final-review',icon:'↻',color:'violet',title:'Повторение продуктов и скрипта',eyebrow:'День 04 · подготовка',lead:'Закрепите продукты, первый разговор и работу с возражениями перед практикой.',sources:['Повторение продуктов и скрипта'],practice:'product-cert',check:COURSES[4].check,content:traineeLesson('Повторение продуктов и скрипта','Повторите СПК, аттестацию, ISO, СУОТ, лицензии МВД/МЧС и сертификацию продукции.',[{title:'Готовность к практике',items:['Могу объяснить клиенту, что именно надо уточнить по его продукту.','Не называю цену и срок без проверки маршрута.','Умею перевести возражение в вопрос и зафиксировать следующий контакт.']}])},
    {id:'tr-cold-calls',icon:'☎',color:'violet',title:'10 учебных сценариев и анализ',eyebrow:'День 04 · практика',lead:'Самостоятельно разберите десять сценариев: цель — не количество, а качественная диагностика и следующий шаг.',sources:['10 учебных сценариев и анализ'],practice:'sales',check:COURSES[5].check,content:traineeLesson('10 учебных сценариев и анализ','Цель практики — не количество набранных номеров, а качественная диагностика и понятный следующий шаг.',[{title:'После каждого сценария',items:['Зафиксируйте результат в учебной карточке.','Запишите, что удалось выяснить и какая была договорённость.','Отметьте причину отказа или отсутствия интереса без оценочных формулировок.']},{title:'После серии',text:'Сравните свои ответы с критериями: есть ли факты, польза и конкретное следующее действие.'}])},
    {id:'tr-first-kp',icon:'▣',color:'violet',title:'Первое КП и итоговая аттестация',eyebrow:'День 04 · результат',lead:'Самостоятельно подготовьте первое КП по кейсу и завершите экзамен.',sources:['Первое КП и итоговая аттестация'],practice:'sales',check:COURSES[5].check,content:traineeLesson('Первое КП и итоговая аттестация','Перед отправкой КП проверьте, что в нём отражены факты запроса и назначена дата обсуждения.',[{title:'Итоговое задание',items:['Подготовьте первое КП самостоятельно по учебному кейсу.','Передайте его на проверку РОПу.','Пройдите итоговую аттестацию: вопросы по продуктам, скрипту, CRM и развёрнутый кейс.']}])}
  ];
  const TRAINEE_FOUNDATION_COURSES = [
    {id:'tr-company-video',icon:'▶',color:'teal',title:'Компания и отдел продаж',eyebrow:'День 01 · знакомство',lead:'Посмотрите вводное видео: чем занимается Mavis, кто наши клиенты и как устроена работа продаж.',sources:['Компания и отдел продаж'],practice:'sales',check:COURSES[5].check,content:traineeLesson('Компания и отдел продаж','Mavis помогает организациям разобраться с требованиями к документам, компетенциям и системам управления. Роль менеджера — не назначить документ «на глаз», а понять задачу и провести клиента к правильному маршруту.',[{title:'Вводное видео',text:'Посмотрите запись целиком. Затем вернитесь к карточкам продуктов: видео даёт общий контекст, а карточки объясняют, что именно спрашивать и зачем.'},{title:'Как устроена работа',items:['Клиент описывает задачу: виды работ, объект, продукцию, требование заказчика или тендера.','Менеджер задаёт вопросы, фиксирует подтверждённые факты в CRM и назначает следующий контакт.','Эксперт проверяет требования и состав документов, когда для решения не хватает данных или нужна специальная оценка.','Менеджер возвращается к клиенту с понятным маршрутом, а не с непроверенным обещанием.']},{title:'Что должен уметь стажёр после темы',items:['Объяснить простыми словами, чем компания полезна клиенту.','Назвать разницу между задачей клиента и названием документа.','Составить первый список вопросов и зафиксировать конкретный следующий шаг.']}])+`<figure class="trainee-media trainee-video"><iframe title="Видео-обучение Mavis" src="https://docs.google.com/videos/d/1i3c78SieIX4SOQVvViOQ1t5WSzKgY4UuCoqecyZ0fus/play" allow="autoplay; fullscreen" allowfullscreen></iframe><figcaption>Вводное видео. Если встроенный плеер не открылся, <a href="https://docs.google.com/videos/d/1i3c78SieIX4SOQVvViOQ1t5WSzKgY4UuCoqecyZ0fus/play" target="_blank" rel="noopener">откройте видео в Google Vids</a>.</figcaption></figure>`},
    {id:'tr-general',icon:'▤',color:'teal',title:'Общая информация по продуктам',eyebrow:'День 01 · продукты',lead:'Базовая логика работы с продуктами: как понять задачу клиента до выбора документа.',sources:['Общая информация по продуктам'],practice:'spk',check:COURSES[0].check,content:traineeLesson('Общая информация по продуктам','Продукт — это не код и не строка из прайса. Это понятный клиенту маршрут: какую задачу он решает, что нужно проверить до старта и какой результат он получит после прохождения процедуры.',[{title:'Какие задачи решаем',items:['Строительной организации может понадобиться подтверждение производственного контроля или аттестация для определённых работ.','Компании может потребоваться система менеджмента качества ISO 9001 или система управления охраной труда ISO 45001 — например, из-за тендера, требования заказчика или внутренних процессов.','Запрос клиента может относиться к лицензии, сертификации продукции или другому разрешительному документу. Название документа уточняет эксперт, если фактов недостаточно.']},{title:'Как думать в первом разговоре',items:['Сначала спросите, чем занимается компания и что именно она планирует делать, производить или подтверждать.','Уточните причину обращения: требование заказчика, тендер, контракт, проверка, истечение срока или внутреннее решение.','Зафиксируйте срок клиента, но не превращайте его в обещание: сначала необходимо проверить исходные данные и требования.','Спросите, какие документы, специалисты, оборудование или предыдущие сертификаты уже есть.']},{title:'Пять обязательных фактов в карточке клиента',items:['Компания и контактное лицо.','Задача клиента и причина срочности.','Виды работ, объект, продукция или область деятельности.','Действующие документы и недостающие сведения.','Конкретный следующий шаг: кто, что, когда и в каком канале делает.']},{title:'Что нельзя говорить клиенту',items:['«Точно сделаем за …» — пока эксперт не проверил маршрут и комплект.','«Вам нужен именно этот документ» — если вы ещё не знаете виды работ или цель клиента.','«Пришлите всё, что есть» — вместо понятного перечня данных и причины, зачем они нужны.']},{title:'Мини-словарь',items:['Исходные данные — факты и документы, на которых строится проверка: вид работ, объект, штат, действующие документы, срок.','Маршрут — последовательность действий от диагностики до результата и следующего контакта.','Следующий шаг — конкретное действие с датой и ответственным, а не расплывчатое «созвонимся позже».']}])},
    {id:'tr-spk',icon:'▧',color:'teal',title:'СПК: свидетельство о технической компетентности',eyebrow:'День 01 · основной продукт',lead:'Что такое СПК, для каких строительных работ он нужен и как собрать запрос без ошибок.',sources:['СПК'],practice:'spk',check:COURSES[0].check,content:traineeLesson('СПК: свидетельство о технической компетентности','СПК — свидетельство о технической компетентности. Оно связано с производственным контролем строительной организации: компания подтверждает, что у неё есть люди, процессы и средства измерений для заявленных видов работ.',[{title:'Когда тема СПК возникает',items:['Компания выполняет или планирует выполнять строительные, монтажные, инженерные либо специальные работы и хочет подтвердить свою техническую компетентность.','Клиенту нужно понять, какие виды работ можно заявить и какие специалисты или средства измерений понадобятся.','Запрос связан с расширением уже действующего СПК или подготовкой к новому направлению работ.']},{title:'Что выяснить в первом разговоре',items:['Какие именно работы выполняет компания: общестроительные, сантехнические, электромонтажные, дорожные, геодезические или другие. Не ограничивайтесь общим словом «стройка».','На каких объектах и для кого выполняются работы: новое строительство, реконструкция, текущий или капитальный ремонт.','Какие специалисты есть в штате, какие документы подтверждают их квалификацию и кто отвечает за производственный контроль.','Какие средства измерений есть у организации и что из необходимого можно привлечь в аренду.']},{title:'Как проходит маршрут',items:['Менеджер собирает сведения и передаёт их на проверку, если требуется подобрать виды работ или оценить комплект.','По результатам проверки клиент получает понятный перечень недостающих данных, специалистов и средств измерений.','После подготовки комплекта согласовываются дальнейшие действия и срок следующего контакта.','Если речь идёт о другом разрешительном документе или аттестации, маршрут уточняется отдельно: СПК не заменяет все требования для любых работ.']},{title:'Как объяснить ценность',text:'Клиент получает не случайный список документов, а проверенный перечень того, что относится именно к его работам. Это снижает риск заявить неподходящий вид работ или начать подготовку с неполного комплекта.'},{title:'Что нельзя обещать',text:'Не обещайте, что одного СПК достаточно для всех работ, и не называйте срок или состав требований до проверки видов работ, объекта, специалистов и исходных документов.'}])},
    {id:'tr-att-st',icon:'⌂',color:'orange',title:'Аттестация строительной деятельности',eyebrow:'День 01 · продукт',lead:'Как понять, нужен ли организации аттестат, какие данные собрать и как проходит маршрут.',sources:['Аттестация СТ'],practice:'spk',check:COURSES[1].check,content:traineeLesson('Аттестация строительной деятельности','Аттестация подтверждает возможность организации выполнять заявленные строительные направления. Внутренние сокращения не важны для клиента: важно понять конкретные работы, класс и объект, потому что от них зависят специалисты и комплект документов.',[{title:'Когда обсуждаем аттестацию',items:['Компания планирует выполнять строительные работы, для которых требуется подтверждение компетенции организации.','Клиент расширяет направления работ, меняет класс объектов или хочет подтвердить действующий аттестат.','Заказчик, тендер или договор требует аттестат по конкретному направлению.']},{title:'Что спросить у клиента',items:['Какие работы он будет выполнять: например, общестроительные, электромонтажные, сантехнические, дорожные или инженерные.','На каком объекте и в какой роли работает компания: подрядчик, генподрядчик, субподрядчик.','Какие специалисты есть: должность, образование, стаж, аттестаты; какие документы уже действуют.','Какой срок важен клиенту и почему.']},{title:'Как идёт подготовка',items:['Сначала проверяется соответствие работ, специалистов и документов заявленному направлению.','После проверки формируется понятный перечень недостающих документов или специалистов.','Комплект готовится, подписывается и проходит установленную процедуру рассмотрения. При замечаниях исправляется именно указанная часть комплекта.','Результат и последующие действия фиксируются в сделке: счёт, договор, замечания или дата следующего контакта.']},{title:'Как говорить с клиентом',text:'«Я уточню ваши виды работ и специалистов, чтобы эксперт проверил, какой маршрут и комплект подходят именно вашей организации. После проверки согласуем состав документов и следующий шаг». '},{title:'Не обещаем',text:'Не гарантируйте выдачу аттестата, соответствие направления или точную дату до экспертной проверки исходных данных.'}])},
    {id:'tr-att-gs',icon:'⌂',color:'orange',title:'Аттестация: отдельное направление работ',eyebrow:'День 01 · продукт',lead:'Как собирать запрос по отдельному направлению аттестации и не спутать его с другой процедурой.',sources:['Аттестация ГС'],practice:'spk',check:COURSES[1].check,content:traineeLesson('Аттестация: отдельное направление работ','У строительной аттестации есть направления с разными требованиями. Поэтому менеджер не выбирает решение по короткому названию услуги: он собирает факты и передаёт их на проверку.',[{title:'Почему это отдельная карточка',text:'Похожее на слух название работ не означает одинаковый набор требований. Например, для разных направлений могут понадобиться специалисты с разными профилями, иной состав документов или другой класс объекта.'},{title:'Первый разговор: последовательность',items:['Попросите клиента описать планируемые работы своими словами и уточните объект.','Спросите, выполняла ли компания такие работы раньше и какие документы уже есть.','Соберите сведения о специалистах: должности, профиль, стаж и действующие подтверждения.','Зафиксируйте срок и его причину: тендер, договор, начало работ или продление документа.']},{title:'Передача эксперту',items:['Передайте не только название услуги, а краткое описание работ, объекта, роли компании и собранные документы.','Отдельно перечислите, что подтверждено и каких данных не хватает.','После ответа эксперта не пересказывайте требования приблизительно: направьте клиенту точный перечень и согласуйте срок предоставления.']},{title:'Проверка себя',items:['Я могу объяснить клиенту, зачем мы задаём вопросы о работах и специалистах.','В карточке есть не только запрос «нужен аттестат», но и его фактическое содержание.','Я не пообещал(а) результат без проверки.']}])},
    {id:'tr-iso-cert',icon:'◌',color:'violet',title:'Сертификат ISO 9001: система качества',eyebrow:'День 01 · ISO',lead:'Что подтверждает ISO 9001, когда он нужен и как организация готовится к сертификации.',sources:['Сертификат ISO 9001'],practice:'iso-suot',check:COURSES[2].check,content:traineeLesson('Сертификат ISO 9001: система качества','ISO 9001 — сертификат системы менеджмента качества. Он показывает, что компания управляет своими процессами качества, а не просто оформляет разовый документ. Его часто запрашивают для тендера, контракта или как подтверждение зрелых внутренних процессов.',[{title:'Когда клиенту может быть нужен ISO 9001',items:['В тендере или договоре прямо указано требование ISO 9001.','Заказчик просит подтвердить систему управления качеством поставщика или подрядчика.','Руководитель хочет описать, закрепить и регулярно проверять процессы компании.']},{title:'Что выяснить до старта',items:['Кто и зачем запросил сертификат: заказчик, тендер, внутреннее решение.','Какую деятельность нужно включить в область сертификации: строительство, производство, услуги или другое направление.','Есть ли действующий сертификат, прошлые документы и ближайший срок, который нельзя пропустить.','Какие специалисты, документы, объекты и процессы уже есть у клиента.']},{title:'Что готовится',items:['Политика и цели в области качества, приказы и распределение ответственности.','Описание процессов, внутренние аудиты, реестр рисков и мероприятия по управлению ими.','Сведения о сотрудниках, поставщиках и объектах, а также документы, которые понадобятся при проверке.']},{title:'Как проходит процедура',items:['Сначала проверяются область деятельности и исходные данные.','Готовится комплект и согласуется его содержание с клиентом.','Орган сертификации проводит проверку, при необходимости — выезд или аудит.','По замечаниям корректируется конкретный документ или процесс; после успешного прохождения результат вносится в реестр.']},{title:'Что нельзя обещать',text:'Нельзя гарантировать выдачу или срок до проверки области деятельности, комплекта документов и готовности к процедуре.'}])},
    {id:'tr-iso-periodic',icon:'↻',color:'violet',title:'ISO 9001: периодическая оценка',eyebrow:'День 01 · ISO',lead:'Как поддерживать действующий сертификат ISO 9001 и не пропустить ежегодную проверку.',sources:['Периодическая оценка ISO 9001'],practice:'iso-suot',check:COURSES[2].check,content:traineeLesson('ISO 9001: периодическая оценка','Периодическая оценка — это не оформление нового ISO «с нуля», а подтверждение, что система качества продолжает работать после выдачи сертификата. Её нужно планировать заранее, потому что пропуск контрольного срока может повлиять на действие документа.',[{title:'Что проверить сразу',items:['Номер, область действия, дату выдачи и дату окончания действующего сертификата.','Когда должна пройти ближайшая периодическая оценка.','В каком органе был получен сертификат и какие условия применяются к проверке.']},{title:'Какие изменения важны',items:['Изменилась ли деятельность, область сертификации, штат, адреса или объекты.','Обновлялись ли ключевые документы: политика, цели, внутренние аудиты, реестр рисков, приказы и журналы.','Есть ли замечания прошлой проверки и все ли они закрыты.']},{title:'Как вести клиента',items:['Объясните, что проверка подтверждает действующую систему, поэтому нужны актуальные факты, а не только старый сертификат.','Согласуйте перечень документов, срок их передачи и дату следующего контакта.','После проверки зафиксируйте недостающее и передайте точные задачи ответственному, а не общий запрос «подготовить документы».']},{title:'Не обещаем',text:'Не называйте дату прохождения и не утверждайте, что оценка пройдена, пока орган не проверил актуальный комплект.'}])},
    {id:'tr-suot-cert',icon:'◌',color:'violet',title:'СУОТ 45001: сертификат и подготовка',eyebrow:'День 01 · СУОТ',lead:'Полный маршрут: когда нужен сертификат, что проверить, какие документы готовятся и как проходит сертификация.',sources:['СУОТ 45001: сертификат и подготовка'],practice:'iso-suot',check:COURSES[2].check,content:traineeLesson('СУОТ 45001: сертификат и подготовка','СТБ ISO 45001-2020 подтверждает действующую систему управления охраной труда. Это добровольный сертификат, который используют для тендеров, требований заказчика и подтверждения системной работы с профессиональными рисками.',[{title:'Когда предлагать',items:['Клиент участвует в тендере или закупке, где требуют ISO 45001.','Заказчик просит подтвердить систему охраны труда.','Компании нужно выстроить и подтвердить управление рисками, инструктажами и охраной труда.']},{title:'Что сначала уточнить',items:['Цель оформления, требование заказчика или тендера и желаемый срок.','Область деятельности компании и действующие разрешительные документы.','Есть ли в штате три руководящих специалиста с удостоверениями по охране труда; для строительной области — есть ли аттестованный специалист.']},{title:'Что входит в подготовку',items:['Политика и цели по охране труда, приказы, инструкции, журналы и формы.','Реестр рисков, мероприятия по управлению ими, программа внутренних аудитов и документы по проверке знаний.','Комплект документов для органа сертификации и подготовка к выезду эксперта.']},{title:'Как проходит работа',items:['Собираем исходные данные: сотрудники, поставщики, объект, документы и журналы.','Подаём заявку, запрашиваем договор и счёт у органа сертификации.','Готовим комплект, согласовываем область и штат, направляем на предварительную проверку.','Перед выездом эксперт проверяет распечатанные и подписанные документы; замечания исправляются до внесения сертификата в реестр.']},{title:'Важные сроки',items:['Сертификат действует 3 года.','Периодическая оценка проводится ежегодно в срок от даты начала действия; пропуск срока может привести к отмене сертификата.']},{title:'Что нельзя обещать',text:'Нельзя гарантировать выдачу, называть точную дату или заменять требования закона одной только сертификацией без проверки исходных данных.'}])},
    {id:'tr-suot-periodic',icon:'↻',color:'violet',title:'СУОТ 45001: ежегодная оценка',eyebrow:'День 01 · СУОТ',lead:'Как подтвердить действие системы охраны труда, подготовиться к ежегодной оценке и не потерять срок.',sources:['СУОТ 45001: ежегодная оценка'],practice:'iso-suot',check:COURSES[2].check,content:traineeLesson('СУОТ 45001: ежегодная оценка','Ежегодная оценка подтверждает, что система управления охраной труда продолжает работать: риски выявляются, документы ведутся, сотрудники проходят необходимые процедуры. Это не «продление по одной бумаге», а проверка актуальности всей системы.',[{title:'Что проверяется',items:['Дата выдачи, срок действия сертификата и дата ближайшей ежегодной оценки.','Изменения в деятельности, штате, объектах, процессах и профессиональных рисках.','Актуальность политики, целей, приказов, инструкций, журналов, реестра рисков и документов по охране труда.','Выполнение мероприятий и закрытие замечаний прошлой проверки, если они были.']},{title:'Что запросить у клиента',items:['Действующий сертификат и сведения об органе, который проводил сертификацию.','Информацию об изменениях после прошлой оценки: новые виды работ, сотрудники, объекты или риски.','Актуальные документы и подтверждение, кто ответственен за систему охраны труда.']},{title:'Как вести процесс',items:['Сверьте контрольную дату и объясните, почему документы нужно собрать заранее.','Составьте конкретный перечень недостающего: документ, ответственный и дата предоставления.','Передайте обновлённый комплект на проверку и зафиксируйте следующую договорённость в сделке.','По замечаниям исправляйте обозначенные элементы системы, а не заменяйте документы случайными шаблонами.']},{title:'Что нельзя обещать',text:'Не обещайте прохождение ежегодной оценки до проверки комплекта и не утверждайте, что старый сертификат автоматически подтверждает актуальность системы.'}])},
    {id:'tr-case-kp',icon:'✎',color:'yellow',title:'Кейс: первый звонок и КП',eyebrow:'День 02 · задание',lead:'Подготовьте свой сценарий первого звонка и коммерческое предложение по учебному кейсу.',sources:['Кейс: первый звонок и КП'],practice:'sales',check:COURSES[5].check,content:traineeLesson('Кейс: первый звонок и КП','Подготовьте текст не как заученный монолог, а как план живого разговора, который приводит к следующему действию.',[{title:'Сценарий первого звонка',items:['Приветствие и причина обращения.','Вопросы о компании, задаче, сроке, работах или продукции.','Короткая презентация пользы на основе ответов клиента.','Проверка понимания: всё ли ясно, что осталось уточнить.','Договорённость о КП: какие данные нужны и когда его обсудите.','Следующее касание: дата, канал, действие и ответственный.']},{title:'КП по кейсу',items:['Зафиксируйте подтверждённые факты запроса.','Покажите подходящий маршрут и состав работ.','Не называйте неподтверждённый срок или результат.','Назначьте дату обсуждения КП.']}])}
  ];
