  function courseBrief(course){const facts=COURSE_BRIEFS[course.id]||[], route=course.id.startsWith('tr-')||!course.check?.order?.length?'':flowDiagram([course.check.order.join(' → ')]);return `<section class="course-brief"><div><span>ПЕРЕД ЧТЕНИЕМ</span><h3>Опорная карта темы</h3></div><div>${facts.map(([title,text])=>`<article><b>${esc(title)}</b><p>${esc(text)}</p></article>`).join('')}</div></section>${route}${detailedTheory(course)}`;}
